import org.gradle.api.tasks.testing.logging.TestExceptionFormat

// The Kotlin bindings of kraken-ffi (scripts/bindings.sh kotlin) tested on the JVM, with the library
// of the host. Android and the other targets: platforms/kotlin-multiplatform
//
//   ./gradlew :kraken-kotlin:test
plugins {
    alias(additionals.plugins.kotlin.jvm)
    id("jvmCompat")
}

// generated by scripts/bindings.sh kotlin
val bindings = rootDir.resolve("dist/bindings/kotlin")
// the directory of libkraken_ffi for the host: target/debug, built by scripts/bindings.sh
val libraryDir: String = providers.gradleProperty("krakenLibraryDir")
    .getOrElse(rootDir.resolve("target/debug").absolutePath)

java {
    val version = JavaVersion.toVersion(rootProject.extra["javaVersion"] as String)
    sourceCompatibility = version
    targetCompatibility = version
}

sourceSets {
    main {
        kotlin.srcDir(bindings)
    }
}

// the uniffi bindings hold unused expressions, flagged since Kotlin 2.4
kotlin {
    compilerOptions {
        freeCompilerArgs.add("-Xwarning-level=UNUSED_EXPRESSION:disabled")
    }
}

dependencies {
    implementation(libs.jna)
    implementation(additionals.kotlinx.coroutines.core)

    testImplementation(additionals.junit)
    testImplementation(additionals.kotlinx.coroutines.test)
    testImplementation(additionals.okhttp.mockwebserver)
}

tasks.compileKotlin {
    doFirst {
        check(bindings.resolve("uniffi").isDirectory) {
            "no bindings in $bindings: run scripts/bindings.sh kotlin"
        }
    }
}

tasks.test {
    systemProperty("jna.library.path", libraryDir)
    testLogging {
        events("passed", "skipped", "failed")
        exceptionFormat = TestExceptionFormat.FULL
    }
}
